// Mode itération : chaque exécution reçoit un seul club.
const club = $input.item.json;

// Vérifier les deux critères.
const hasSite = !!club.website && String(club.website).startsWith('http');
const sansActivites = !club.activities || (Array.isArray(club.activities) && club.activities.length === 0);

// Ne passer au nœud suivant que si les deux critères sont vrais.
if (hasSite && sansActivites) {
  return [{ json: { id: club.id, name: club.name, city: club.city, website: club.website } }];
} else {
  return []; // Skip ce club
}

// Mode itération : chaque exécution reçoit un seul club.
const club = $input.item.json;

// Nettoie le HTML → texte brut tronqué.
const html = String($json.data ?? $json.body ?? '');
const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&[a-z]+;/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 6000);

// Site injoignable ou vide → on saute ce club.
if (!text || text.length < 40) return [];

const ACTIVITIES = [
  'Moussaillon', 'Optimist', 'Dériveur', 'Catamaran',
  'Planche à voile / WindSurf', 'WingFoil', 'WindFoil', 'KiteSurf',
  'KiteFoil', 'E-Foil', 'Surf', 'Kayak', 'Paddle',
  'Habitable/Croisière', 'Char à voile',
];

const system =
  "Tu es un assistant qui analyse le site web d'un club nautique français. " +
  'À partir du texte du site, tu dois : ' +
  '1) Identifier UNIQUEMENT les activités proposées par le club, parmi cette liste exacte (n\'invente rien, n\'ajoute aucune autre valeur) : ' +
  ACTIVITIES.join(', ') + '. ' +
  '2) Rédiger une description en français, optimisée SEO autour du mot-clé "voile", de 2 à 4 phrases. ' +
  'Elle doit présenter le club et mentionner naturellement les activités associées à la ville sous la forme "Activité à Ville" (ex : "Catamaran à ' + club.city + '"). ' +
  "Ne recopie jamais l'adresse postale. Reste factuel : ne mentionne que des activités réellement présentes sur le site. " +
  'Réponds STRICTEMENT au format JSON demandé.';

const body = {
  model: 'claude-haiku-4-5',
  max_tokens: 1024,
  system,
  messages: [
    {
      role: 'user',
      content:
        'Nom du club : ' + club.name + '\n' +
        'Ville : ' + club.city + '\n\n' +
        'Contenu du site web :\n' + text,
    },
  ],
  output_config: {
    format: {
      type: 'json_schema',
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          activities: { type: 'array', items: { type: 'string', enum: ACTIVITIES } },
          description: { type: 'string' },
        },
        required: ['activities', 'description'],
      },
    },
  },
};

return [{ json: { id: club.id, name: club.name, city: club.city, body } }];

// Parse la réponse structurée de Claude et valide les activités.
const ACTIVITIES = [
  'Moussaillon', 'Optimist', 'Dériveur', 'Catamaran',
  'Planche à voile / WindSurf', 'WingFoil', 'WindFoil', 'KiteSurf',
  'KiteFoil', 'E-Foil', 'Surf', 'Kayak', 'Paddle',
  'Habitable/Croisière', 'Char à voile',
];

let parsed;
try {
  const txt = $json.content?.[0]?.text ?? '';
  parsed = JSON.parse(txt);
} catch (e) {
  return []; // réponse inattendue → on saute
}

const activities = (parsed.activities || []).filter((a) => ACTIVITIES.includes(a));
const description = String(parsed.description || '').trim();
const club = $input.item.json;
const id = club.id;

if (!id || (activities.length === 0 && !description)) return [];

return [{ json: { id, activities, description } }];
